style.css:
@-moz-document domain("youtube.com") {
/* MATRIX COLORS */
:root {
    --matrix-green: #00ff41;
    --matrix-dark: #020702;
    --matrix-panel: #071207;
    --matrix-light: #8aff9c;
}

/* GLOBAL */
html,
body,
ytd-app {
    background: var(--matrix-dark) !important;
    color: var(--matrix-green) !important;
}

/* MAIN HEADER */
#masthead,
ytd-masthead,
#container.ytd-masthead {
    background: #010501 !important;
    border-bottom: 1px solid var(--matrix-green) !important;
    box-shadow: 0 2px 15px #00ff4140 !important;
}

/* LOGO AREA */
#logo-icon,
yt-icon {
    color: var(--matrix-green) !important;
}

/* SEARCH BAR */
#search-form,
ytd-searchbox {
    background: #061006 !important;
    border: 1px solid var(--matrix-green) !important;
    border-radius: 12px !important;
    box-shadow: 0 0 8px #00ff4130 !important;
}

#search,
#search-input input,
#search-input {
    background: transparent !important;
    color: var(--matrix-light) !important;
}

/* SEARCH BUTTON */
#search-icon-legacy {
    background: #092009 !important;
    color: var(--matrix-green) !important;
    border: 1px solid var(--matrix-green) !important;
}

/* SIDEBAR */
ytd-guide-renderer,
ytd-mini-guide-renderer,
#guide-content {
    background: #020802 !important;
}

ytd-guide-entry-renderer,
ytd-mini-guide-entry-renderer {
    color: var(--matrix-green) !important;
    border-radius: 10px !important;
    transition: 0.25s ease !important;
}

ytd-guide-entry-renderer:hover {
    background: #103010 !important;
    box-shadow: 0 0 12px #00ff4150 !important;
}

/* VIDEO CARDS */
ytd-rich-item-renderer,
ytd-video-renderer,
ytd-compact-video-renderer,
ytd-grid-video-renderer {
    background: #050d05 !important;
    border-radius: 12px !important;
    transition: transform 0.25s ease,
                box-shadow 0.25s ease !important;
}

ytd-rich-item-renderer:hover,
ytd-video-renderer:hover {
    box-shadow: 0 0 15px #00ff4160 !important;
}

/* VIDEO TITLES */
#video-title,
ytd-rich-grid-media #video-title {
    color: var(--matrix-light) !important;
}

#video-title:hover {
    color: var(--matrix-green) !important;
    text-shadow: 0 0 8px var(--matrix-green) !important;
}

/* CHANNEL NAMES */
#channel-name,
#owner,
.ytd-channel-name {
    color: #56c96b !important;
}

/* BUTTONS */
yt-button-shape button,
ytd-button-renderer button,
button {
    transition: 0.25s ease !important;
}

yt-button-shape button:hover,
ytd-button-renderer button:hover {
    box-shadow: 0 0 12px var(--matrix-green) !important;
}

/* SUBSCRIBE BUTTON */
ytd-subscribe-button-renderer button {
    background: #073007 !important;
    color: var(--matrix-green) !important;
    border: 1px solid var(--matrix-green) !important;
}

/* VIDEO PLAYER */
.html5-video-player {
    background: #000 !important;
    border: 1px solid #00ff4140 !important;
    border-radius: 10px !important;
}

/* COMMENTS */
ytd-comment-thread-renderer,
ytd-comments {
    background: #050d05 !important;
}

/* INPUT FIELDS */
input,
textarea,
#contenteditable-root {
    color: var(--matrix-green) !important;
    caret-color: var(--matrix-green) !important;
}

/* PANELS */
ytd-popup-container,
tp-yt-paper-dialog,
ytd-menu-popup-renderer {
    background: #061006 !important;
    color: var(--matrix-green) !important;
    border: 1px solid #00ff4160 !important;
}

/* GENERAL TEXT */
h1, h2, h3, p,
#text,
#metadata-line {
    color: var(--matrix-light) !important;
}

/* NEON LINKS */
a {
    transition: color 0.2s ease,
                text-shadow 0.2s ease !important;
}

a:hover {
    color: var(--matrix-green) !important;
    text-shadow: 0 0 7px var(--matrix-green) !important;
}

/* SCROLLBAR */
::-webkit-scrollbar {
    width: 10px;
}

::-webkit-scrollbar-track {
    background: #010501;
}

::-webkit-scrollbar-thumb {
    background: #008f25;
    border: 2px solid #010501;
    border-radius: 10px;
}

::-webkit-scrollbar-thumb:hover {
    background: var(--matrix-green);
    box-shadow: 0 0 10px var(--matrix-green);
}

/* MATRIX GLOW ANIMATION */
@keyframes matrixGlow {
    0%, 100% {
        box-shadow: 0 0 3px #00ff4140;
    }
    50% {
        box-shadow: 0 0 12px #00ff4190;
    }
}

ytd-rich-item-renderer:hover,
#search-form:focus-within {
    animation: matrixGlow 2s infinite ease-in-out;
}

/* SUBTLE SCANLINE EFFECT */
ytd-app::after {
    content: "";
    position: fixed;
    inset: 0;
    pointer-events: none;
    z-index: 9999;
    opacity: 0.10;
    background: repeating-linear-gradient(
        0deg,
        transparent 0px,
        transparent 3px,
        #00ff4110 4px
    );
}

/* END MATRIX THEME */
}
